package com.carebridge.backend.security;
import static org.junit.jupiter.api.Assertions.assertTrue;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;import com.carebridge.backend.common.config.JpaAuditingConfig;import com.carebridge.backend.config.MockMvcSecurityBuilderConfig;import com.carebridge.backend.partner.controller.PartnerApprovalController;import com.carebridge.backend.partner.service.PartnerApprovalService;import com.carebridge.backend.security.config.SecurityConfig;import com.carebridge.backend.security.jwt.JwtTokenProvider;import com.carebridge.backend.security.repository.UserRepository;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.*;import org.springframework.http.MediaType;import org.springframework.security.test.context.support.WithMockUser;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import org.springframework.web.bind.annotation.RequestMethod;import org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerMapping;
@WebMvcTest(value=PartnerApprovalController.class,excludeFilters=@ComponentScan.Filter(type=FilterType.ASSIGNABLE_TYPE,classes=JpaAuditingConfig.class))@Import({SecurityConfig.class,MockMvcSecurityBuilderConfig.class})class PartnerApprovalControllerSecurityTest{static final String URL="/api/v1/admin/partners/fd000000-0000-0000-0000-000000000001/decision",BODY="{\"decision\":\"APPROVE\"}";@Autowired MockMvc mvc;@Autowired RequestMappingHandlerMapping mappings;@MockitoBean PartnerApprovalService service;@MockitoBean JwtTokenProvider jwt;@MockitoBean UserRepository users;@Test @WithMockUser(roles="MODERATOR")void appTc609_nonAdminReturns403()throws Exception{mvc.perform(post(URL).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(BODY)).andExpect(status().isForbidden());}@Test @WithMockUser(roles="PARTNER")void appTc610_partnerCannotSelfApprove()throws Exception{mvc.perform(post(URL).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(BODY)).andExpect(status().isForbidden());}@Test void appTc611_noJwtReturns401()throws Exception{assertTrue(mappings.getHandlerMethods().keySet().stream().anyMatch(i->i.getPatternValues().contains("/api/v1/admin/partners/{partnerId}/decision")&&i.getMethodsCondition().getMethods().contains(RequestMethod.POST)));mvc.perform(post(URL).contentType(MediaType.APPLICATION_JSON).content(BODY)).andExpect(status().isUnauthorized());}}
